import { ConflictError, DomainError, normalizeToBaseError } from "@zudojs/errors";

function toBody(thrown: unknown) {
  const error = normalizeToBaseError(thrown);
  if (error.expose && error.statusCode < 500) {
    return [error.statusCode, { error: { code: error.code, message: error.message } }];
  }
  return [500, { error: { code: "INTERNAL", message: "Something went wrong on our side" } }];
}

