function errorBody(problem, requestId) {
  if (problem.status >= 500) {
    return { error: { code: "INTERNAL", message: "Something went wrong on our side", requestId } };
  }
  const error = { code: problem.code, message: problem.message };
  if (problem.issues && problem.issues.length > 0) error.issues = problem.issues;
  return { error };
}

const examples = [
  { status: 400, code: "VALIDATION_FAILED", message: "The request is not valid", issues: [{ path: "limit", message: "Expected <= 50" }] },
  { status: 404, code: "ERR_RESOURCE_NOT_FOUND", message: "Order 7 not found", issues: [] },
  { status: 500, code: "ERR_DATABASE", message: 'relation "products" does not exist' },
];
for (const problem of examples) console.log(JSON.stringify(errorBody(problem, "req-1")));

