const stock = new Map([["rice", 3], ["zobo", 10]]);

function placeOrder(stock, items) {
  const skus = items.map((item) => item.sku);
  if (new Set(skus).size !== skus.length) throw new Error("List each product once");
  for (const { sku, quantity } of items) {
    if ((stock.get(sku) ?? 0) < quantity) throw new Error(`Not enough stock for ${sku}`);
  }
  for (const { sku, quantity } of items) stock.set(sku, stock.get(sku) - quantity);
}

for (const items of [
  [{ sku: "zobo", quantity: 4 }, { sku: "rice", quantity: 5 }],
  [{ sku: "rice", quantity: 1 }, { sku: "rice", quantity: 1 }],
  [{ sku: "rice", quantity: 2 }, { sku: "zobo", quantity: 4 }],
]) {
  try {
    placeOrder(stock, items);
    console.log("placed");
  } catch (error) {
    console.log(error.message);
  }
}
console.log([...stock]);

