function formatNaira(kobo) {
  const naira = Math.floor(kobo / 100);
  const rest = kobo % 100;
  const grouped = String(naira).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return `₦${grouped}.${String(rest).padStart(2, "0")}`;
}

for (const kobo of [2705997, 50000, 5]) console.log(formatNaira(kobo));

